  "brain.py": "\"\"\"Real-world-neurons brain - a plain function, an MCP server, an HTTP edge.\n\n    python brain.py\n    curl -s localhost:8000/summarise -H 'content-type: application/json' -d '{\"text\": \"...\"}'\n    curl -s localhost:8000/files\n\n    summary-node  hosts a Neuron that is a plain async function\n    files-node    hosts an Effector over the filesystem MCP server\n    api-node      hosts the HTTP Receptor - TASKs to summary, TOOL_CALLs to files\n\"\"\"\nimport asyncio\nimport contextlib\nimport signal\n\nfrom cosmonapse import Dendrite, MemorySynapse, connect_synapse, run_brain\n\nfrom config import NAMESPACE, SYNAPSE_URL\nfrom effector import files\nfrom neurons import summary\nfrom receptors import api\n\n\ndef build_summary(synapse) -> Dendrite:\n    node = Dendrite(synapse=synapse, namespace=NAMESPACE,\n                    dendrite_id=\"summary-node\", role=\"worker\")\n    node.attach_axon(summary.AXON)\n    return node\n\n\ndef build_files(synapse) -> Dendrite:\n    \"\"\"attach_effector is all it takes: this node now services TOOL_CALLs\n    addressed to files-effector.\"\"\"\n    node = Dendrite(synapse=synapse, namespace=NAMESPACE,\n                    dendrite_id=\"files-node\", role=\"worker\")\n    node.attach_effector(files.EFFECTOR)\n    return node\n\n\ndef build_api(synapse) -> Dendrite:\n    node = Dendrite(synapse=synapse, namespace=NAMESPACE,\n                    dendrite_id=\"api-node\", heartbeat_s=0)\n    node.attach_receptor(api.RECEPTOR)\n    return node\n\n\ndef _stop_on_signals() -> None:\n    \"\"\"Ctrl-C / SIGTERM cancel the task so run_brain can unwind every node.\"\"\"\n    task = asyncio.current_task()\n    loop = asyncio.get_running_loop()\n    for sig in (signal.SIGINT, signal.SIGTERM):\n        with contextlib.suppress(NotImplementedError, AttributeError):\n            loop.add_signal_handler(sig, task.cancel)\n\n\nasync def main() -> int:\n    _stop_on_signals()\n    if SYNAPSE_URL:\n        synapse = await connect_synapse(SYNAPSE_URL)\n    else:\n        synapse = MemorySynapse()      # in-process bus - no broker, no setup\n        await synapse.connect()\n    try:\n        return await run_brain(\n            build_summary(synapse),\n            build_files(synapse),\n            build_api(synapse),\n        )\n    except asyncio.CancelledError:\n        return 0\n    finally:\n        await synapse.close()\n\n\nif __name__ == \"__main__\":\n    try:\n        raise SystemExit(asyncio.run(main()))\n    except KeyboardInterrupt:\n        raise SystemExit(130)\n",
